import{_ as e,o as i,c as o,aa as n}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/en/tickets/en_editace_ukolu2.png",a="/buildary-help-preview/media/en/tickets/en_vyjadreni.png",r="/buildary-help-preview/media/en/tickets/en_diskuze2.png",c="/buildary-help-preview/media/en/tickets/en_historie.png",d="/buildary-help-preview/media/en/tickets/en_navaz_zaznam_esd.png",l="/buildary-help-preview/media/cs/tickets/ikona_ukol-esd.png",h="/buildary-help-preview/media/en/tickets/en_navaz_ukol.png",p="/buildary-help-preview/media/en/tickets/en_ukol_volby.png",T=JSON.parse('{"title":"Edit Ticket","description":"","frontmatter":{"title":"Edit Ticket","wiki":"en:tickets:task_edit"},"headers":[],"relativePath":"en/tickets/task_edit.md","filePath":"en/tickets/task_edit.md","lastUpdated":1794388980000}'),g={name:"en/tickets/task_edit.md"};function k(u,t,m,f,_,y){return i(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="edit-ticket" tabindex="-1">Edit Ticket <a class="header-anchor" href="#edit-ticket" aria-label="Permalink to &quot;Edit Ticket&quot;">​</a></h1><figure class="shot" style="--w:500px;"><img src="'+s+'" alt="Ticket Details" width="480" loading="lazy"></figure><p>The <strong>Ticket Details (edit) page</strong> can be accessed from any part of Ticket Management by <strong>clicking the Subject of the ticket or a link</strong> (on a drawing or map).</p><p><strong>In terms of permissions:</strong></p><p>The <strong>Author</strong> of the ticket can edit all information.</p><p>The <strong>Assignee</strong> of the ticket can edit only the Ticket Status and Label, and add a Statement or a post to the Discussion.</p><p>The <strong>Approver</strong> can edit the same information as the Assignee, plus change the location on the map or drawing, add attachments to the ticket, and modify the people listed under Assignees and Approvers.</p><p><strong>In terms of working with tickets,</strong> users will most often open Ticket Details to:</p><p>**change the Ticket Status,</p><p>add a Statement,</p><p>participate in the Discussion, or</p><p>view complete information about the ticket.**</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+a+'" alt="Statement" width="500" loading="lazy"></figure><p>At the end of the form, there is a <strong>Conclusion</strong> section. Any authorized user can add information relevant to the ticket here.</p><p><strong>The user can:</strong></p><p><strong>Add Conclusion</strong>, which creates a new thread, or</p><p><strong>React</strong>, which adds a response to an existing thread.</p><p>Attachments in any format can be added to these records.</p><p>Only the author of a record can <strong>edit or delete</strong> it, and only until another user responds to it. Once a response is added, the record is locked against further changes or deletion.</p><p>If the response is removed, the record is unlocked.</p><h2 id="discussion-and-history" tabindex="-1">Discussion and History <a class="header-anchor" href="#discussion-and-history" aria-label="Permalink to &quot;Discussion and History&quot;">​</a></h2><p>The <strong>Discussion and History</strong> link above the ticket form on the right opens a panel on the right side containing the discussion, with an option to switch to the history of changes made to the ticket.</p><figure class="shot" style="--w:600px;"><img src="'+r+'" alt="Discussion" width="600" loading="lazy"></figure><p><strong>Ticket Discussion</strong> is used for informal exchange of information.</p><p>The content of the discussion <strong>is not included in any export</strong>, unlike Statements.</p><p>In the Discussion panel, <strong>changes to the Ticket Status</strong> are also displayed alongside the posts.</p><p>The <strong>Ticket History</strong> records all changes made to the ticket, including the author and timestamp:</p><img src="'+c+'" alt="History" width="250" loading="lazy"><h2 id="related-items" tabindex="-1">Related Items <a class="header-anchor" href="#related-items" aria-label="Permalink to &quot;Related Items&quot;">​</a></h2><p>If there is a <strong>related item linked to the ticket</strong>, either an <strong>orange icon on the right</strong> or a <strong>blue icon on the left</strong> is displayed next to the Discussion and History link. Which icon is displayed depends on whether the related item is a ticket or a record in the Project Diary:</p><img src="'+d+'" alt="Related Project Diary Record" width="300" loading="lazy"><p>The blue icon on the left indicates that <strong>this ticket is linked to a Project Diary record</strong>. Clicking it opens the relevant Project Diary in a new browser tab, on the day containing the record.</p><p>The <strong>Project Diary record</strong> linked to the ticket is located either in the <strong>Performed Works or Additional Records</strong> section and can be identified by the icon <img src="'+l+'" alt="Ticket Linked to Project Diary Record" width="40" data-no-zoom loading="lazy"></p><img src="'+h+'" alt="Related Ticket" width="300" loading="lazy"><p>The orange icon on the right indicates that <strong>this ticket is linked to another ticket</strong>. Clicking it opens a <strong>window with a list of related tickets</strong>, from which the user can navigate to the details of a related ticket.</p><h2 id="more-options" tabindex="-1">More Options <a class="header-anchor" href="#more-options" aria-label="Permalink to &quot;More Options&quot;">​</a></h2><p>The <strong>Three-Dot Menu on the right above the Ticket Details form</strong> can be used to expand options for:</p><figure class="shot" style="--w:270px;"><img src="'+p+'" alt="More Ticket Options" width="250" loading="lazy"></figure><ul><li>Create a Copy of the Ticket → opens the New Ticket form and copies selected information into it</li><li>Create Related Ticket → opens the New Ticket form with a link to the current ticket</li><li>Download as PDF → exports the ticket to a PDF file</li><li>Delete Ticket → deletes the ticket</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If some options are inactive (grayed out), the user does not have permission to use them.</p></div>',41)])])}const b=e(g,[["render",k]]);export{T as __pageData,b as default};
